+  }
+
+  followRoute(p, dt) {
+    const pt = p.route[p.routeIndex];
+    if (!pt) { p.scripted = false; p.route = null; return; }
+    const dx = pt.x - p.x;
+    const dy = pt.y - p.y;
+    const d = Math.hypot(dx, dy);
+    if (d < 0.85) {
+      p.routeIndex++;
