28:   } else if (pattern === 'sash') {
29:     ctx.save();
30:     ctx.translate(x + w / 2, y + h / 2);
31:     ctx.rotate(-0.55);
32:     ctx.fillRect(-w * 1.2, -h * 0.13, w * 2.4, h * 0.26);
33:     ctx.restore();
34:   } else if (pattern === 'shoulders') {
35:     ctx.fillRect(x, y, w, h * 0.3);
36:   }
37:   ctx.restore();
38: }
