40: function hairShape(ctx, style, color, x, y, r) {
41:   ctx.fillStyle = color;
42:   if (style === 'bald') return;
43:   if (style === 'buzz' || style === 'short') {
44:     ctx.beginPath();
45:     ctx.arc(x - r * 0.15, y, r * 1.05, Math.PI * 0.55, Math.PI * 1.55);
46:     ctx.fill();
47:     return;
48:   }
49:   if (style === 'curly') {
50:     for (let i = 0; i < 7; i++) {
51:       const a = Math.PI * 0.45 + (i / 7) * Math.PI * 1.1;
52:       ctx.beginPath();
53:       ctx.arc(x + Math.cos(a) * r * 0.9, y + Math.sin(a) * r * 0.9, r * 0.42, 0, TAU);
54:       ctx.fill();
55:     }
56:     return;
57:   }
58:   if (style === 'long') {
59:     ctx.beginPath();
60:     ctx.ellipse(x - r * 0.15, y + r * 0.25, r * 1.25, r * 1.5, 0, 0, TAU);
61:     ctx.fill();
62:     return;
63:   }
64:   if (style === 'afro') {
65:     ctx.beginPath();
66:     ctx.arc(x - r * 0.2, y, r * 1.55, 0, TAU);
67:     ctx.fill();
68:     return;
69:   }
70: }
71: 
72: function headgear(ctx, gear, colors, x, y, r) {
73:   if (gear === 'headband') {
74:     ctx.strokeStyle = colors.secondary;
75:     ctx.lineWidth = r * 0.34;
76:     ctx.beginPath();
77:     ctx.arc(x, y, r * 0.92, -Math.PI * 0.9, Math.PI * 0.9);
78:     ctx.stroke();
79:   } else if (gear === 'scrumcap') {
80:     ctx.fillStyle = colors.secondary;
81:     ctx.beginPath();
82:     ctx.arc(x - r * 0.08, y, r * 1.13, 0, TAU);
83:     ctx.fill();
84:     ctx.strokeStyle = 'rgba(0,0,0,0.24)';
85:     ctx.lineWidth = r * 0.1;
86:     ctx.beginPath();
87:     ctx.arc(x - r * 0.08, y, r * 1.13, 0, TAU);
88:     ctx.stroke();
89:     ctx.fillStyle = colors.primary;
90:     ctx.beginPath();
91:     ctx.arc(x + r * 0.28, y, r * 0.5, -Math.PI / 2, Math.PI / 2);
92:     ctx.fill();
93:   }
94: }
