96: export function drawPlayerSprite(ctx, p, sx, sy, zoom, time = 0, opts = {}) {
97:   const colors = p.team?.colors || { primary: '#f2c53d', secondary: '#0d2b1c', shorts: '#0d2b1c', socks: '#f2c53d', pattern: 'sash' };
98:   const app = p.appearance || {};
99:   const scale = zoom * 1.34;
100:   const r = scale * 0.42;
101:   const state = p.state || 'run';
102:   const run = p.runPhase || 0;
103:   const speed = Math.hypot(p.vx || 0, p.vy || 0);
104:   const moving = speed > 0.6;
105:   const sprint = p.sprintReq && moving;
106:   const controlled = opts.controlled;
107:   const down = state === 'down';
108:   const diving = state === 'dive';
109: 
110:   ctx.save();
111:   ctx.translate(sx, sy);
112: 
113:   // ground shadow
114:   ctx.fillStyle = `rgba(0,0,0,${down ? 0.2 : 0.32})`;
115:   ctx.beginPath();
116:   ctx.ellipse(2, 4, r * 1.15, r * 0.8, 0, 0, TAU);
117:   ctx.fill();
118: 
119:   // selection / script rings
120:   if (opts.scripted) {
121:     ctx.strokeStyle = 'rgba(242,197,61,0.55)';
122:     ctx.lineWidth = 2;
123:     ctx.setLineDash([4, 4]);
124:     ctx.beginPath();
125:     ctx.arc(0, 0, r * 1.75, 0, TAU);
126:     ctx.stroke();
127:     ctx.setLineDash([]);
128:   }
129:   if (controlled) {
130:     const pulse = 0.5 + Math.sin(time * 5) * 0.18;
131:     ctx.strokeStyle = `rgba(216,243,106,${pulse})`;
132:     ctx.lineWidth = 2.5;
133:     ctx.beginPath();
134:     ctx.arc(0, 0, r * 1.75, 0, TAU);
135:     ctx.stroke();
136:     ctx.fillStyle = 'rgba(216,243,106,0.1)';
137:     ctx.beginPath();
138:     ctx.arc(0, 0, r * 1.75, 0, TAU);
139:     ctx.fill();
140:     // arrow
141:     ctx.fillStyle = '#d8f36a';
142:     ctx.beginPath();
143:     ctx.moveTo(0, -r * 2.55);
144:     ctx.lineTo(-r * 0.42, -r * 2.05);
145:     ctx.lineTo(r * 0.42, -r * 2.05);
146:     ctx.closePath();
147:     ctx.fill();
148:   }
149: 
150:   ctx.rotate((diving ? (p.diveAngle ?? p.facing ?? 0) : (p.facing ?? 0)));
151:   if (down) {
152:     ctx.rotate(1.15);
153:     ctx.scale(1, 0.7);
154:     ctx.globalAlpha = 0.85;
155:   }
156:   if (state === 'getup') {
157:     ctx.scale(0.82, 0.82);
158:   }
159:   ctx.scale(scale, scale);
160:   ctx.lineJoin = 'round';
161:   ctx.lineCap = 'round';
162: 
163:   const legSwing = moving ? Math.sin(run) * 0.26 : Math.sin(time * 1.4 + (p.slot || 0)) * 0.03;
164:   const armSwing = moving ? Math.sin(run + Math.PI) * 0.2 : 0;
165:   const sock = colors.socks || colors.primary;
166:   const shorts = colors.shorts || colors.secondary;
167:   const dark = shade(colors.secondary || '#111', -0.2);
168: 
169:   // legs
170:   if (!down) {
171:     ctx.strokeStyle = sock;
172:     ctx.lineWidth = 0.17;
173:     ctx.beginPath();
174:     ctx.moveTo(-0.18, -0.14);
175:     ctx.lineTo(-0.5 + legSwing, -0.19);
176:     ctx.stroke();
177:     ctx.beginPath();
178:     ctx.moveTo(-0.18, 0.14);
179:     ctx.lineTo(-0.5 - legSwing, 0.19);
180:     ctx.stroke();
181:     ctx.strokeStyle = '#161616';
182:     ctx.lineWidth = 0.13;
183:     ctx.beginPath();
184:     ctx.moveTo(-0.5 + legSwing, -0.19);
185:     ctx.lineTo(-0.68 + legSwing, -0.22);
186:     ctx.stroke();
187:     ctx.beginPath();
188:     ctx.moveTo(-0.5 - legSwing, 0.19);
189:     ctx.lineTo(-0.68 - legSwing, 0.22);
190:     ctx.stroke();
191:     // shorts
192:     ctx.fillStyle = shorts;
193:     ctx.beginPath();
194:     ctx.ellipse(-0.17, 0, 0.19, 0.3, 0, 0, TAU);
195:     ctx.fill();
196:   }
197: 
198:   // arms behind torso
199:   if (!down) {
200:     const armY = diving ? 0.3 : 0.33;
201:     const armX = diving ? 0.65 : 0.05 + armSwing;
202:     ctx.strokeStyle = app.skin || '#d99e70';
203:     ctx.lineWidth = 0.14;
204:     ctx.beginPath();
205:     ctx.moveTo(0.05, -0.27);
206:     ctx.lineTo(armX, -armY);
207:     ctx.stroke();
208:     ctx.beginPath();
209:     ctx.moveTo(0.05, 0.27);
210:     ctx.lineTo(armX, armY);
211:     ctx.stroke();
212:     // sleeves
213:     ctx.strokeStyle = colors.secondary;
214:     ctx.lineWidth = 0.17;
215:     ctx.beginPath();
216:     ctx.moveTo(0.03, -0.26);
217:     ctx.lineTo(0.16, -0.29);
218:     ctx.stroke();
219:     ctx.beginPath();
220:     ctx.moveTo(0.03, 0.26);
221:     ctx.lineTo(0.16, 0.29);
222:     ctx.stroke();
223:   }
224: 
225:   // torso
226:   ctx.beginPath();
227:   ctx.ellipse(0, 0, 0.42, 0.32, 0, 0, TAU);
228:   ctx.save();
229:   ctx.clip();
230:   jerseyPattern(ctx, -0.5, -0.4, 1.0, 0.8, colors, colors.pattern);
231:   ctx.restore();
232:   ctx.strokeStyle = 'rgba(0,0,0,0.35)';
233:   ctx.lineWidth = 0.035;
234:   ctx.beginPath();
235:   ctx.ellipse(0, 0, 0.42, 0.32, 0, 0, TAU);
236:   ctx.stroke();
237: 
238:   // number
239:   ctx.save();
240:   ctx.rotate(Math.PI);
241:   ctx.fillStyle = 'rgba(255,255,255,0.85)';
242:   ctx.font = '700 0.27px Inter, system-ui, sans-serif';
243:   ctx.textAlign = 'center';
244:   ctx.textBaseline = 'middle';
245:   ctx.fillText(String(p.number ?? ''), 0.02, 0);
246:   ctx.restore();
247: 
248:   // head
249:   const hx = 0.3;
250:   ctx.save();
251:   // hair behind
252:   hairShape(ctx, app.hairStyle, app.hair || '#241811', hx - 0.05, 0, 0.22);
253:   // neck
254:   ctx.fillStyle = app.skin || '#d99e70';
255:   ctx.beginPath();
256:   ctx.arc(hx, 0, 0.21, 0, TAU);
257:   ctx.fill();
258:   // face shading
259:   ctx.fillStyle = 'rgba(0,0,0,0.1)';
260:   ctx.beginPath();
261:   ctx.arc(hx + 0.08, 0.05, 0.14, 0, TAU);
262:   ctx.fill();
263:   headgear(ctx, app.gear, colors, hx, 0, 0.22);
264:   ctx.restore();
265: 
266:   if (state === 'celebrate' || p.celebrate > 0) {
267:     ctx.strokeStyle = app.skin || '#d99e70';
268:     ctx.lineWidth = 0.14;
269:     ctx.beginPath();
270:     ctx.moveTo(0.05, -0.22);
271:     ctx.lineTo(-0.05, -0.58);
272:     ctx.moveTo(0.05, 0.22);
273:     ctx.lineTo(-0.05, 0.58);
274:     ctx.stroke();
275:   }
276: 
277:   ctx.restore();
278: 
279:   if (down) {
280:     ctx.save();
281:     ctx.translate(sx, sy);
282:     ctx.fillStyle = 'rgba(245,240,227,0.75)';
283:     for (let i = 0; i < 3; i++) {
284:       const a = time * 2 + i * 2.1;
285:       ctx.beginPath();
286:       ctx.arc(Math.cos(a) * r * 1.2, -r * 1.6 + Math.sin(a) * 3, 1.5, 0, TAU);
287:       ctx.fill();
288:     }
289:     ctx.restore();
290:   }
291: }
