296: export function drawPortrait(canvas, player, team, opts = {}) {
297:   const ctx = canvas.getContext('2d');
298:   const W = canvas.width, H = canvas.height;
299:   const dpr = Math.min(window.devicePixelRatio || 1, 2);
300:   if (canvas.dataset.cssw !== String(canvas.clientWidth)) {
301:     canvas.dataset.cssw = String(canvas.clientWidth);
302:   }
303:   ctx.clearRect(0, 0, W, H);
304:   const colors = team?.colors || { primary: '#f2c53d', secondary: '#0d2b1c', shorts: '#0d2b1c', socks: '#f2c53d', pattern: 'sash' };
305:   const app = player?.appearance || { skin: '#d99e70', hair: '#241811', hairStyle: 'short', build: 'athletic', gear: 'none' };
306:   const S = Math.min(W, H);
307:   const cx = W / 2;
308:   const top = H * 0.1;
309: 
310:   // backdrop
311:   const g = ctx.createRadialGradient(cx, H * 0.42, S * 0.05, cx, H * 0.5, S * 0.7);
312:   g.addColorStop(0, alpha(colors.primary, 0.18));
313:   g.addColorStop(0.5, alpha(colors.primary, 0.05));
314:   g.addColorStop(1, 'rgba(0,0,0,0)');
315:   ctx.fillStyle = g;
316:   ctx.fillRect(0, 0, W, H);
317:   // pitch stripes
318:   ctx.save();
319:   ctx.globalAlpha = 0.07;
320:   for (let i = 0; i < 9; i++) {
321:     if (i % 2 === 0) {
322:       ctx.fillStyle = '#d8f36a';
323:       ctx.fillRect(0, H * (i / 9), W, H / 9);
324:     }
325:   }
326:   ctx.restore();
327:   // big number
328:   ctx.save();
329:   ctx.globalAlpha = 0.06;
330:   ctx.fillStyle = colors.primary;
331:   ctx.font = `900 ${S * 0.72}px "Arial Narrow", Impact, sans-serif`;
332:   ctx.textAlign = 'center';
333:   ctx.textBaseline = 'middle';
334:   ctx.fillText(String(player?.number ?? ''), cx, H * 0.48);
335:   ctx.restore();
336: 
337:   const build = app.build === 'power' ? 1.12 : app.build === 'slim' ? 0.9 : 1;
338:   const bodyW = S * 0.23 * build;
339:   const bodyH = S * 0.32;
340:   const bodyY = top + S * 0.26;
341:   const headR = S * 0.085 * (app.build === 'power' ? 1.04 : 1);
342:   const skin = app.skin || '#d99e70';
343: 
344:   // shadow
345:   ctx.fillStyle = 'rgba(0,0,0,0.35)';
346:   ctx.beginPath();
347:   ctx.ellipse(cx, H * 0.925, bodyW * 1.45, S * 0.03, 0, 0, TAU);
348:   ctx.fill();
349: 
350:   // legs
351:   const legW = bodyW * 0.36;
352:   ctx.fillStyle = colors.shorts || '#0d2b1c';
353:   roundRect(ctx, cx - bodyW * 0.45, bodyY + bodyH * 0.72, legW, S * 0.12, legW * 0.25);
354:   ctx.fill();
355:   roundRect(ctx, cx + bodyW * 0.09, bodyY + bodyH * 0.72, legW, S * 0.12, legW * 0.25);
356:   ctx.fill();
357:   // thighs
358:   ctx.fillStyle = skin;
359:   roundRect(ctx, cx - bodyW * 0.43, bodyY + bodyH * 0.83, legW * 0.9, S * 0.16, legW * 0.3);
360:   ctx.fill();
361:   roundRect(ctx, cx + bodyW * 0.11, bodyY + bodyH * 0.83, legW * 0.9, S * 0.16, legW * 0.3);
362:   ctx.fill();
363:   // socks
364:   ctx.fillStyle = colors.socks || colors.primary;
365:   roundRect(ctx, cx - bodyW * 0.43, bodyY + bodyH * 0.95, legW * 0.92, S * 0.115, 3);
366:   ctx.fill();
367:   roundRect(ctx, cx + bodyW * 0.11, bodyY + bodyH * 0.95, legW * 0.92, S * 0.115, 3);
368:   ctx.fill();
369:   // boots
370:   ctx.fillStyle = '#171717';
371:   roundRect(ctx, cx - bodyW * 0.47, H * 0.885, legW * 1.1, S * 0.03, 4);
372:   ctx.fill();
373:   roundRect(ctx, cx + bodyW * 0.07, H * 0.885, legW * 1.1, S * 0.03, 4);
374:   ctx.fill();
375: 
376:   // torso
377:   ctx.save();
378:   const torsoPath = () => {
379:     ctx.beginPath();
380:     ctx.moveTo(cx - bodyW * 0.72, bodyY + S * 0.04);
381:     ctx.quadraticCurveTo(cx - bodyW * 0.98, bodyY + bodyH * 0.55, cx - bodyW * 0.55, bodyY + bodyH * 0.86);
382:     ctx.quadraticCurveTo(cx, bodyY + bodyH * 0.98, cx + bodyW * 0.55, bodyY + bodyH * 0.86);
383:     ctx.quadraticCurveTo(cx + bodyW * 0.98, bodyY + bodyH * 0.55, cx + bodyW * 0.72, bodyY + S * 0.04);
384:     ctx.quadraticCurveTo(cx, bodyY - S * 0.02, cx - bodyW * 0.72, bodyY + S * 0.04);
385:     ctx.closePath();
386:   };
387:   torsoPath();
388:   ctx.clip();
389:   jerseyPattern(ctx, cx - bodyW, bodyY - S * 0.03, bodyW * 2, bodyH * 1.02, colors, colors.pattern || opts.pattern);
390:   // subtle fabric shading
391:   const shadeGrad = ctx.createLinearGradient(cx - bodyW, 0, cx + bodyW, 0);
392:   shadeGrad.addColorStop(0, 'rgba(0,0,0,0.25)');
393:   shadeGrad.addColorStop(0.4, 'rgba(255,255,255,0.08)');
394:   shadeGrad.addColorStop(0.75, 'rgba(0,0,0,0.1)');
395:   shadeGrad.addColorStop(1, 'rgba(0,0,0,0.28)');
396:   ctx.fillStyle = shadeGrad;
397:   ctx.fillRect(cx - bodyW, bodyY - S * 0.04, bodyW * 2, bodyH);
398:   ctx.restore();
399:   torsoPath();
400:   ctx.strokeStyle = 'rgba(0,0,0,0.32)';
401:   ctx.lineWidth = 2;
402:   ctx.stroke();
403: 
404:   // collar
405:   ctx.fillStyle = colors.secondary;
406:   ctx.beginPath();
407:   ctx.ellipse(cx, bodyY + S * 0.025, headR * 0.75, headR * 0.32, 0, 0, TAU);
408:   ctx.fill();
409:   // sleeves
410:   ctx.fillStyle = colors.secondary;
411:   ctx.beginPath();
412:   ctx.ellipse(cx - bodyW * 0.82, bodyY + S * 0.08, bodyW * 0.23, S * 0.075, -0.4, 0, TAU);
413:   ctx.fill();
414:   ctx.beginPath();
415:   ctx.ellipse(cx + bodyW * 0.82, bodyY + S * 0.08, bodyW * 0.23, S * 0.075, 0.4, 0, TAU);
416:   ctx.fill();
417: 
418:   // arms crossed
419:   ctx.strokeStyle = skin;
420:   ctx.lineWidth = bodyW * 0.27;
421:   ctx.lineCap = 'round';
422:   ctx.beginPath();
423:   ctx.moveTo(cx - bodyW * 0.82, bodyY + S * 0.085);
424:   ctx.quadraticCurveTo(cx - bodyW * 0.5, bodyY + bodyH * 0.48, cx - bodyW * 0.06, bodyY + bodyH * 0.37);
425:   ctx.stroke();
426:   ctx.beginPath();
427:   ctx.moveTo(cx + bodyW * 0.82, bodyY + S * 0.085);
428:   ctx.quadraticCurveTo(cx + bodyW * 0.5, bodyY + bodyH * 0.5, cx + bodyW * 0.03, bodyY + bodyH * 0.47);
429:   ctx.stroke();
430:   // hands
431:   ctx.fillStyle = skin;
432:   ctx.beginPath();
433:   ctx.arc(cx - bodyW * 0.06, bodyY + bodyH * 0.37, bodyW * 0.15, 0, TAU);
434:   ctx.fill();
435:   ctx.beginPath();
436:   ctx.arc(cx + bodyW * 0.03, bodyY + bodyH * 0.47, bodyW * 0.15, 0, TAU);
437:   ctx.fill();
438: 
439:   // number on chest
440:   ctx.fillStyle = 'rgba(255,255,255,0.92)';
441:   ctx.font = `800 ${S * 0.16}px "Arial Narrow", Impact, sans-serif`;
442:   ctx.textAlign = 'center';
443:   ctx.textBaseline = 'middle';
444:   ctx.fillText(String(player?.number ?? ''), cx, bodyY + bodyH * 0.65);
445:   // crest
446:   ctx.fillStyle = colors.secondary;
447:   ctx.beginPath();
448:   ctx.arc(cx - bodyW * 0.42, bodyY + bodyH * 0.18, S * 0.023, 0, TAU);
449:   ctx.fill();
450:   ctx.strokeStyle = colors.primary;
451:   ctx.lineWidth = 1;
452:   ctx.stroke();
453: 
454:   // neck & head
455:   ctx.fillStyle = shade(skin, -0.08);
456:   roundRect(ctx, cx - headR * 0.42, bodyY - headR * 0.45, headR * 0.84, headR * 0.8, headR * 0.2);
457:   ctx.fill();
458:   // hair back
459:   hairShape(ctx, app.hairStyle, app.hair || '#241811', cx - headR * 0.08, bodyY - headR * 1.55, headR * 1.05);
460:   // head
461:   ctx.fillStyle = skin;
462:   ctx.beginPath();
463:   ctx.ellipse(cx, bodyY - headR * 1.55, headR, headR * 1.15, 0, 0, TAU);
464:   ctx.fill();
465:   // ears
466:   ctx.beginPath();
467:   ctx.arc(cx - headR * 0.98, bodyY - headR * 1.52, headR * 0.22, 0, TAU);
468:   ctx.arc(cx + headR * 0.98, bodyY - headR * 1.52, headR * 0.22, 0, TAU);
469:   ctx.fill();
470:   // face
471:   ctx.fillStyle = 'rgba(0,0,0,0.55)';
472:   ctx.beginPath();
473:   ctx.arc(cx - headR * 0.36, bodyY - headR * 1.62, headR * 0.075, 0, TAU);
474:   ctx.arc(cx + headR * 0.36, bodyY - headR * 1.62, headR * 0.075, 0, TAU);
475:   ctx.fill();
476:   ctx.strokeStyle = 'rgba(0,0,0,0.28)';
477:   ctx.lineWidth = Math.max(1, headR * 0.08);
478:   ctx.beginPath();
479:   ctx.arc(cx, bodyY - headR * 1.3, headR * 0.26, 0.25, Math.PI - 0.25);
480:   ctx.stroke();
481:   // hair front
482:   if (app.hairStyle !== 'bald') {
483:     ctx.fillStyle = app.hair || '#241811';
484:     ctx.beginPath();
485:     ctx.ellipse(cx - headR * 0.12, bodyY - headR * 2.05, headR * 0.95, headR * 0.48, -0.08, Math.PI, TAU);
486:     ctx.fill();
487:   }
488:   headgear(ctx, app.gear, colors, cx, bodyY - headR * 1.55, headR * 1.02);
489: 
490:   // ball under arm
491:   if (opts.ball) {
492:     ctx.save();
493:     ctx.translate(cx + bodyW * 0.95, bodyY + bodyH * 0.4);
494:     ctx.rotate(0.45);
495:     ctx.fillStyle = '#8a4b2a';
496:     ctx.beginPath();
497:     ctx.ellipse(0, 0, S * 0.075, S * 0.05, 0, 0, TAU);
498:     ctx.fill();
499:     ctx.strokeStyle = '#f5f0e3';
500:     ctx.lineWidth = 1.2;
501:     ctx.beginPath();
502:     ctx.moveTo(-S * 0.03, 0);
503:     ctx.lineTo(S * 0.03, 0);
504:     ctx.stroke();
505:     ctx.restore();
506:   }
507:   // vignette
508:   const v = ctx.createRadialGradient(cx, H * 0.5, S * 0.2, cx, H * 0.5, S * 0.72);
509:   v.addColorStop(0, 'rgba(0,0,0,0)');
510:   v.addColorStop(1, 'rgba(0,0,0,0.38)');
511:   ctx.fillStyle = v;
512:   ctx.fillRect(0, 0, W, H);
513: }
