600: export function playEditorTransform(w, h) {
601:   const pad = 26;
602:   const minX = -32, maxX = 58, minY = -35, maxY = 35;
603:   const s = Math.min((w - pad * 2) / (maxX - minX), (h - pad * 2) / (maxY - minY));
604:   const ox = (w - (maxX - minX) * s) / 2 - minX * s;
605:   const oy = (h - (maxY - minY) * s) / 2 - minY * s;
606:   return {
607:     s, ox, oy,
608:     toScreen: (x, y) => ({ x: ox + x * s, y: oy + y * s }),
609:     toWorld: (px, py) => ({ x: (px - ox) / s, y: (py - oy) / s }),
610:   };
611: }
