97: export function makePlayer({ name, position, number, trait, appearance, stats, id }) {
98:   const pos = POSITION_BY_ID[position] || POSITIONS[0];
99:   const base = { ...pos.stats };
100:   const variance = STAT_VARIANCE[position] || {};
101:   const finalStats = {};
102:   for (const k of STAT_KEYS) {
103:     finalStats[k] = clamp(Math.round(stats?.[k] ?? base[k] + (variance[k] || 0)), STAT_MIN, STAT_MAX);
104:   }
105:   return {
106:     id: id || uid('p'),
107:     name,
108:     number: Number(number) || 1,
109:     position,
110:     trait: trait || 'none',
111:     appearance: { ...(appearance || DEFAULT_APPEARANCES[0]) },
112:     stats: finalStats,
113:     bench: pos.group === 'Bench',
114:     stamina: 100,
115:   };
116: }
