280: export function buildRivalTeam(opp, difficulty = 'normal', seed = 0) {
281:   const players = [];
282:   const diffBump = difficulty === 'hard' ? 2 : difficulty === 'easy' ? -3 : 0;
283:   const baseRating = clamp(opp.rating + diffBump, 60, 92);
284:   const positions = ['prop', 'hooker', 'flanker', 'scrumhalf', 'flyhalf', 'centre', 'winger'];
285:   const benchPos = ['utility', 'forward', 'back'];
286:   const names = shuffle(opp.names);
287:   const usedNames = new Set();
288:   for (let i = 0; i < 7; i++) {
289:     const pos = positions[i];
290:     const base = POSITION_BY_ID[pos].stats;
291:     const targetAvg = (baseRating - 45) / 5.5;
292:     const stats = {};
293:     for (const k of STAT_KEYS) {
294:       // blend position template toward target average
295:       const v = base[k] * 0.55 + targetAvg * 0.45 + (i % 3 === 0 ? 0.4 : 0);
296:       stats[k] = clamp(Math.round(v + (Math.random() < 0.35 ? 1 : 0)), 2, 10);
297:     }
298:     let name = names.find((n) => !usedNames.has(n)) || `${RIVAL_FIRST_NAMES[i]} Rival`;
299:     usedNames.add(name);
300:     const p = makePlayer({
301:       name,
302:       position: pos,
303:       number: i + 1,
304:       trait: ['enforcer', 'speedster', 'engine', 'playmaker', 'bigboot', 'magician', 'safehands'][(i + seed) % 7],
305:       appearance: {
306:         skin: SKIN_TONES[(i + seed) % SKIN_TONES.length],
307:         hair: HAIR_COLORS[(i + seed + 2) % HAIR_COLORS.length],
308:         hairStyle: HAIR_STYLES[(i + seed) % HAIR_STYLES.length].id,
309:         build: i % 3 === 0 ? 'power' : i % 3 === 1 ? 'athletic' : 'slim',
310:         gear: i === 1 ? 'headband' : 'none',
311:       },
312:       stats,
313:     });
314:     players.push(p);
315:   }
316:   for (let i = 0; i < 3; i++) {
317:     const pos = benchPos[i];
318:     const base = POSITION_BY_ID[pos].stats;
319:     const stats = {};
320:     for (const k of STAT_KEYS) stats[k] = clamp(base[k] + (baseRating > 78 ? 1 : 0), 2, 10);
321:     players.push(makePlayer({
322:       name: `${RIVAL_FIRST_NAMES[(i + 5) % RIVAL_FIRST_NAMES.length]} ${opp.abbr === 'BUL' ? 'Storm' : opp.abbr === 'SHK' ? 'Reef' : opp.abbr === 'RAM' ? 'Braid' : 'Crown'}`,
323:       position: pos,
324:       number: 8 + i,
325:       trait: ['engine', 'safehands', 'speedster'][i],
326:       appearance: { ...DEFAULT_APPEARANCES[(i + 3) % DEFAULT_APPEARANCES.length] },
327:       stats,
328:     }));
329:   }
330:   return {
331:     id: opp.id,
332:     name: opp.name,
333:     abbr: opp.abbr,
334:     colors: { ...opp.colors },
335:     squad: players,
336:     tactics: { attack: opp.style, defense: opp.defense },
337:     overall: baseRating,
338:     isAI: true,
339:   };
340: }
