        if (xx < -20 || xx > this.w + 20) continue;
        const h = hash(c * 3.3 + r * 9.1);
        const v = 0.16 + h * 0.28;
        ctx.fillStyle = h > 0.82 ? `rgba(242,197,61,${v})` : h > 0.7 ? `rgba(216,243,106,${v})` : `rgba(245,240,227,${v})`;
