const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('node:path');

const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const BASE = 'http://localhost:3000/?qa=' + Date.now();

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto(BASE, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  console.log('title:', await page.title());
  console.log('screens active:', await page.locator('.screen.active').getAttribute('id'));
  console.log('menu tip:', await page.locator('#menu-tip').textContent());
  await page.screenshot({ path: path.join(OUT, 'qa-menu.png') });

  // Navigate quick match
  await page.click('[data-go="setup"]');
  await page.waitForTimeout(400);
  console.log('after setup click:', await page.locator('.screen.active').getAttribute('id'));
  await page.screenshot({ path: path.join(OUT, 'qa-setup.png') });

  // start a 90s half match for faster QA
  await page.click('[data-half="90"]');
  await page.click('#start-match-btn');
  await page.waitForTimeout(900);
  const info = await page.evaluate(() => {
    const m = window.__ruckus.match;
    return m ? { state: m.state, clock: m.clock, players: m.teams.map(t => t.players.length), controlled: m.controlled?.name, screen: window.__ruckus.ui.screen, paused: window.__ruckus.ui.paused } : null;
  });
  console.log('match info:', JSON.stringify(info));
  await page.screenshot({ path: path.join(OUT, 'qa-kickoff.png') });

  // let kickoff run
  await page.waitForTimeout(3000);
  console.log('state after 3s:', await page.evaluate(() => window.__ruckus.match.state));
  await page.screenshot({ path: path.join(OUT, 'qa-play1.png') });

  // drive simulation 20 seconds quickly (pause raf updates first)
  const sim = await page.evaluate(() => {
    const { match, ui } = window.__ruckus;
    // pause the render loop updates without overlay
    ui.paused = true;
    const states = {};
    for (let i = 0; i < 60 * 20; i++) {
      if (match.state === 'halftime' || match.state === 'fulltime') break;
      match.update(1 / 60);
      states[match.state] = (states[match.state] || 0) + 1;
    }
    ui.paused = false;
    return { state: match.state, clock: match.clock, score: match.teams.map(t => t.score), states };
  });
  console.log('sim:', JSON.stringify(sim));
  await page.screenshot({ path: path.join(OUT, 'qa-play2.png') });

  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

