const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('node:path');
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.evaluate(() => window.__ruckus.startMatch({ opponent: 'bulls', half: 90, difficulty: 'normal', weather: 'clear' }));
  await page.waitForTimeout(300);

  // --- 1. try + conversion ---------------------------------------------
  const tryRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    ui.paused = true;
    const p = m.userTeam.players[3];
    m.state = 'play';
    m.ball.state = 'held';
    m.ball.owner = p;
    p.x = 99.3; p.y = 35; p.vx = 0; p.vy = 0;
    m.controlled = p;
    p.team.dir = 1;
    let states = [];
    for (let i = 0; i < 180; i++) {
      m.update(1 / 60);
      if (!states.includes(m.state)) states.push(m.state);
      if (m.state === 'conversion') break;
    }
    return { state: m.state, score: m.teams.map(t => t.score), states, conversion: !!m.conversion };
  });
  console.log('tryRes:', JSON.stringify(tryRes));
  await page.screenshot({ path: path.join(OUT, 'qa-try.png') });
  await page.waitForTimeout(600);
  await page.screenshot({ path: path.join(OUT, 'qa-conversion.png') });

  const convRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    if (!m.conversion) return { error: 'no conversion', state: m.state };
    m.conversion.power = 0.7;
    m.lockConversion();
    const states = [];
    for (let i = 0; i < 240; i++) {
      m.update(1 / 60);
      if (!states.includes(m.state)) states.push(m.state);
      if (m.state === 'kickoff') break;
    }
    return { state: m.state, score: m.teams.map(t => t.score), converted: m.teams[0].stats.conversions, states };
  });
  console.log('convRes:', JSON.stringify(convRes));

  // --- 2. halftime ------------------------------------------------------
  const halfRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    m.clock = m.halfLength - 0.01;
    m.state = 'play';
    m.update(1 / 30);
    return { state: m.state, overlay: ui.overlayOpen, paused: ui.paused, html: document.querySelector('#overlay h2')?.textContent };
  });
  console.log('halfRes:', JSON.stringify(halfRes));
  await page.screenshot({ path: path.join(OUT, 'qa-halftime.png') });
  // click start second half
  await page.click('[data-act="second"]');
  await page.waitForTimeout(200);
  const secondRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    m.clock = m.halfLength * 2 - 0.01;
    m.state = 'play';
    m.update(1 / 30);
    return { half: m.half, state: m.state, overlay: ui.overlayOpen, html: document.querySelector('#overlay h2')?.textContent };
  });
  console.log('secondRes:', JSON.stringify(secondRes));
  await page.screenshot({ path: path.join(OUT, 'qa-fulltime.png') });

  // results actions
  console.log('fulltime actions:', await page.locator('#overlay [data-act]').allTextContents());
  await page.click('[data-act="setup"]');
  await page.waitForTimeout(300);
  console.log('after setup act:', await page.locator('.screen.active').getAttribute('id'));

  // --- 3. pause button --------------------------------------------------
  await page.evaluate(() => window.__ruckus.startMatch({ opponent: 'bulls', half: 90, difficulty: 'normal', weather: 'clear' }));
  await page.waitForTimeout(300);
  await page.click('#btn-pause');
  await page.waitForTimeout(300);
  const pauseRes = await page.evaluate(() => {
    const ui = window.__ruckus.ui;
    return { paused: ui.paused, overlay: ui.overlayOpen, html: document.querySelector('#overlay h2')?.textContent };
  });
  console.log('pauseRes:', JSON.stringify(pauseRes));
  await page.screenshot({ path: path.join(OUT, 'qa-pause.png') });
  await page.click('[data-act="resume"]');
  await page.waitForTimeout(200);
  console.log('resumed paused:', await page.evaluate(() => window.__ruckus.ui.paused));

  // --- 4. set piece -----------------------------------------------------
  const setRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    ui.paused = true;
    const team = m.userTeam;
    m.state = 'play';
    m.ball.state = 'held';
    m.ball.owner = team.players[0];
    m.lineoutTo(team, 50, 0);
    const kinds = [m.state];
    m.stopSetpieceBar();
    for (let i = 0; i < 120; i++) { m.update(1 / 60); if (m.state !== 'lineout') break; }
    kinds.push(m.state, m.ball.owner ? 'owner' : 'none');
    // scrum
    m.scrumTo(team, 60, 35, 'KNOCK-ON TEST');
    kinds.push(m.state);
    m.stopSetpieceBar();
    for (let i = 0; i < 120; i++) { m.update(1 / 60); if (m.state !== 'scrum') break; }
    kinds.push(m.state, m.ball.owner ? 'owner' : 'none');
    return { kinds, state: m.state };
  });
  console.log('setRes:', JSON.stringify(setRes));

  // --- 5. custom play ---------------------------------------------------
  const playRes = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    ui.paused = true;
    const team = m.userTeam;
    m.state = 'play';
    m.contact = null; m.ruck = null; m.setpiece = null; m.conversion = null;
    const carrier = team.players[0];
    m.ball.state = 'held'; m.ball.owner = carrier; m.ball.x = carrier.x; m.ball.y = carrier.y;
    carrier.x = 50; carrier.y = 35; carrier.state = 'run';
    m.controlled = carrier;
    const before = m.equippedPlays.map(p => p && p.name);
    m.triggerPlay(0);
    const ap = m.activePlay ? { name: m.activePlay.play.name, receiver: m.activePlay.receiver?.name, passed: m.activePlay.passed } : null;
    let autoPassed = false, newOwner = null;
    for (let i = 0; i < 150; i++) {
      m.update(1 / 60);
      if (m.activePlay && m.activePlay.passed) { autoPassed = true; newOwner = m.ball.owner?.name; break; }
    }
    return { before, ap, autoPassed, newOwner, state: m.state };
  });
  console.log('playRes:', JSON.stringify(playRes));

  // --- 6. quit ----------------------------------------------------------
  await page.evaluate(() => { window.__ruckus.ui.paused = false; });
  await page.waitForTimeout(100);
  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

