    p.x = 100.2; p.y = 35; p.vx = 0; p.vy = 0; p.invuln = 5;
    m.controlled = p;
    const states = [];
    for (let i = 0; i < 400; i++) {
      m.update(1 / 60);
      if (!states.includes(m.state)) states.push(m.state);
