    }
    return { state: m.state, score: m.teams.map(t => t.score), states, conversion: !!m.conversion, trySpot: m.trySpot };
  });
  console.log('tryRes2:', JSON.stringify(res));
  await page.waitForTimeout(700);
  await page.screenshot({ path: path.join(OUT, 'qa-conversion.png') });

  const conv = await page.evaluate(() => {
    const m = window.__ruckus.match;
    if (!m.conversion) return { error: 'no conversion', state: m.state };
    const c = m.conversion;
    const info = { state: m.state, score: m.teams.map(t => t.score), window: c.window, userKicking: c.userKicking, power: c.power, timer: c.timer };
    c.power = 0.7;
    m.lockConversion();
    const states = [];
    for (let i = 0; i < 400; i++) {
      m.update(1 / 60);
      if (!states.includes(m.state)) states.push(m.state);
      if (m.state === 'kickoff' || m.state === 'halftime' || m.state === 'fulltime') break;
    }
    return { ...info, after: { state: m.state, score: m.teams.map(t => t.score), conversions: m.teams.map(t => t.stats.conversions) }, states, success: c.success };
