const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('node:path');
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, userAgent: devices['iPhone 13'].userAgent });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  console.log('coarse:', await page.evaluate(() => window.matchMedia('(hover: none) and (pointer: coarse)').matches), 'w:', await page.evaluate(() => innerWidth));
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-menu.png') });

  await page.tap('[data-go="setup"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-setup.png') });
  // check overflow
  console.log('setup scroll:', await page.evaluate(() => ({ sw: document.querySelector('#screen-setup').scrollWidth, cw: document.querySelector('#screen-setup').clientWidth, sh: document.querySelector('#screen-setup').scrollHeight, ch: document.querySelector('#screen-setup').clientHeight })));

  await page.tap('#start-match-btn');
  await page.waitForTimeout(600);
  const info = await page.evaluate(() => {
    const ui = window.__ruckus.ui;
    const touch = document.getElementById('touch');
    const hud = document.getElementById('hud');
    const bb = (id) => { const el = document.getElementById(id); const r = el?.getBoundingClientRect(); return r ? { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) } : null; };
    return {
      state: window.__ruckus.match.state, touchHidden: touch.classList.contains('hidden'), bodyTouch: document.body.classList.contains('touch-mode'),
      stick: bb('stick-zone'), actions: bb('touch') , hud: bb('hud'),
      scrollW: document.documentElement.scrollWidth, innerW: innerWidth, innerH: innerHeight,
    };
  });
  console.log('mobile match:', JSON.stringify(info));
  await page.waitForTimeout(2000);
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-match.png') });

  // drag joystick
  const stick = await page.locator('#stick-zone').boundingBox();
  if (stick) {
    const cx = stick.x + stick.width / 2, cy = stick.y + stick.height / 2;
    await page.touchscreen.tap(cx, cy); // ensure touch
    // use mouse? pointer events from touchscreen API have no move; use CDP touch? use locator dispatch pointer events
    await page.locator('#stick-zone').dispatchEvent('pointerdown', { pointerId: 1, clientX: cx, clientY: cy, pointerType: 'touch', isPrimary: true });
    await page.locator('#stick-zone').dispatchEvent('pointermove', { pointerId: 1, clientX: cx + 40, clientY: cy - 40, pointerType: 'touch', isPrimary: true });
    await page.waitForTimeout(400);
    const mag = await page.evaluate(() => window.__ruckus ? null : null);
    await page.locator('#stick-zone').dispatchEvent('pointerup', { pointerId: 1, clientX: cx + 40, clientY: cy - 40, pointerType: 'touch', isPrimary: true });
    console.log('joystick drag dispatched');
  }
  // tap actions: switch, sprint, tackle
  for (const action of ['switch', 'sprint', 'tackle']) {
    const b = page.locator(`[data-action="${action}"]`);
    if (await b.count()) { await b.dispatchEvent('pointerdown', { pointerId: 5, pointerType: 'touch', isPrimary: true }); await page.waitForTimeout(80); await b.dispatchEvent('pointerup', { pointerId: 5, pointerType: 'touch', isPrimary: true }); }
  }
  await page.waitForTimeout(600);
  console.log('after touch actions state:', await page.evaluate(() => window.__ruckus.match.state));
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-after-touch.png') });

  // open pause
  await page.tap('#btn-pause');
  await page.waitForTimeout(400);
  console.log('pause overlay:', await page.evaluate(() => window.__ruckus.ui.overlayOpen));
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-pause.png') });
  await page.tap('[data-act="resume"]');

  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

