.stick-base {
  position: absolute; inset: 0; border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(245,240,227,.12), rgba(4,13,8,.55));
  border: 1px solid rgba(245,240,227,.2); backdrop-filter: blur(6px);
}
.stick-knob {
  position: absolute; width: 54px; height: 54px; border-radius: 50%; left: 50%; top: 50%;
  margin: -27px 0 0 -27px; background: rgba(216,243,106,.85); box-shadow: 0 6px 18px rgba(0,0,0,.4);
  transition: transform .05s linear;
}
.touch-actions {
  position: absolute; right: calc(14px + var(--safe-right)); bottom: calc(74px + var(--safe-bottom));
  width: 208px; height: 172px; pointer-events: none;
}
.tbtn {
  position: absolute; pointer-events: auto; border-radius: 50%; border: 1px solid rgba(245,240,227,.22);
  background: rgba(4,13,8,.62); color: var(--cream); font-size: 9px; font-weight: 900; letter-spacing: .06em;
  backdrop-filter: blur(8px); touch-action: none; user-select: none;
  display: grid; place-items: center; transition: transform .08s, background .1s;
}
.tbtn:active, .tbtn.down { transform: scale(.92); background: rgba(216,243,106,.3); }
.tbtn-sprint { width: 52px; height: 52px; right: 150px; top: 104px; font-size: 7px; }
.tbtn-tackle { width: 66px; height: 66px; right: 94px; top: 92px; }
.tbtn-kick { width: 62px; height: 62px; right: 30px; top: 108px; }
.tbtn-pass { width: 58px; height: 58px; right: 104px; top: 26px; }
.tbtn-small { width: 46px; height: 46px; font-size: 7px; }
.touch-actions .tbtn-small[data-action="switch"] { right: 168px; top: 32px; }
.touch-actions .tbtn-small[data-action="sidestep"] { right: 42px; top: 24px; }
.touch-tactics {
  position: absolute; right: calc(14px + var(--safe-right)); bottom: calc(252px + var(--safe-bottom));
  display: flex; gap: 5px; pointer-events: auto;
}
.touch-tactics button {
  width: 30px; height: 30px; border-radius: 8px; border: 1px solid rgba(245,240,227,.18);
  background: rgba(4,13,8,.65); color: var(--lime); font-size: 9px; font-weight: 800;
  display: grid; place-items: center; touch-action: none;
}
.touch-tactics button:active { background: rgba(216,243,106,.3); }
body.touch-mode .hint { display: none; }

/* ============================================================
   OVERLAY / MODALS
   ============================================================ */
.overlay {
  position: fixed; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center;
  background: rgba(3,10,6,.7); backdrop-filter: blur(10px); padding: 20px;
}
.overlay-card {
  width: min(520px, 94vw); max-height: 88vh; overflow-y: auto;
  background: linear-gradient(170deg, rgba(18,48,30,.96), rgba(5,15,9,.98));
  border: 1px solid var(--line-strong); border-radius: 22px; padding: 26px;
  box-shadow: var(--shadow); text-align: center;
  animation: modal-in .32s ease both;
}
@keyframes modal-in { from { opacity: 0; transform: scale(.95) translateY(14px); } to { opacity: 1; transform: none; } }
.overlay-card h2 { font-family: var(--display); font-size: 44px; line-height: .95; margin: 0 0 6px; font-weight: 400; letter-spacing: .04em; text-transform: uppercase; }
.overlay-card .ov-kicker { font-size: 8px; letter-spacing: .24em; color: var(--lime); font-weight: 800; margin-bottom: 8px; }
.overlay-card p { font-size: 11px; line-height: 1.6; color: var(--cream-dim); margin: 8px 0 16px; }
.overlay-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 18px; }
.overlay-actions .btn { justify-content: center; }
.final-score { display: flex; align-items: center; justify-content: center; gap: 18px; margin: 18px 0; }
.final-score .fs-team { flex: 1; }
.final-score .fs-team small { display: block; font-size: 8px; letter-spacing: .14em; color: var(--cream-dim); margin-bottom: 4px; }
.final-score .fs-team b { font-family: var(--display); font-size: 24px; font-weight: 400; letter-spacing: .05em; }
.final-score .fs-score { font-family: var(--display); font-size: 54px; line-height: 1; }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; text-align: left; margin: 14px 0; }
.stat-cell { border: 1px solid var(--line); background: rgba(245,240,227,.03); border-radius: 9px; padding: 8px 10px; display: flex; justify-content: space-between; font-size: 9px; color: var(--cream-dim); }
.stat-cell b { color: var(--cream); font-family: var(--display); font-size: 14px; font-weight: 400; }
.motm { border: 1px solid rgba(242,197,61,.3); background: rgba(242,197,61,.07); border-radius: 11px; padding: 10px 14px; display: flex; align-items: center; justify-content: space-between; margin-top: 6px; }
.motm small { font-size: 7px; letter-spacing: .2em; color: var(--gold); font-weight: 800; }
.motm b { display: block; font-size: 12px; margin-top: 2px; }
.motm .motm-rating { font-family: var(--display); font-size: 30px; color: var(--gold); }
.rtp-bar { height: 6px; border-radius: 99px; background: rgba(245,240,227,.1); margin: 10px 0; overflow: hidden; }
.rtp-bar i { display: block; height: 100%; background: var(--lime); border-radius: 99px; }
.overlay-card .kbd-row { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin: 12px 0 4px; }
.overlay-card .big-k { font-family: var(--display); color: var(--lime); font-size: 18px; letter-spacing: .12em; }

/* ---------------- responsive ---------------- */
@media (max-width: 1180px) {
  .tactics-grid { grid-template-columns: 1fr 1fr; }
  .tactics-side { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
  .tactics-diagram { grid-row: span 2; }
  .tactics-side .btn { align-self: end; }
}
@media (max-width: 980px) {
  .hero-grid { grid-template-columns: 1fr; gap: 24px; }
  .hero-side { display: none; }
  .hero-copy { max-width: 640px; }
  .title { font-size: clamp(64px, 16vw, 120px); }
  .setup-options { grid-template-columns: 1fr; }
  .squad-wrap { grid-template-columns: 240px minmax(0, 1fr); }
  .player-editor { grid-template-columns: 260px minmax(0, 1fr); }
  .plays-layout { grid-template-columns: 210px minmax(0, 1fr); }
  .play-tools { gap: 6px; }
}
@media (max-width: 820px) {
  .screen { padding: calc(14px + var(--safe-top)) calc(14px + var(--safe-right)) calc(16px + var(--safe-bottom)) calc(14px + var(--safe-left)); }
  .pagebar { gap: 12px; padding-bottom: 12px; margin-bottom: 14px; top: calc(-14px - var(--safe-top)); }
  .pagebar-right .pill { display: none; }
  .squad-wrap { grid-template-columns: 1fr; }
  .roster-panel { position: static; max-height: none; }

  .roster-panel { position: static; max-height: none; }
  .roster-list { display: grid; grid-template-columns: 1fr 1fr; max-height: 220px; }
  .kit-panel { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 12px; }
  .kit-panel .panel-mini-title { grid-column: 1 / -1; }
  .kit-colors { grid-column: 1 / -1; grid-template-columns: repeat(4, 1fr); }
  .player-editor { grid-template-columns: 1fr; }
  .portrait-panel { position: static; display: grid; grid-template-columns: 140px 1fr; align-items: center; }
  #portrait-canvas { width: 140px; height: auto; }
  .portrait-meta { border-top: 0; border-left: 1px solid var(--line); }
  .portrait-arrows { grid-column: 1 / -1; }
  .help-grid { grid-template-columns: 1fr; }
  .tactics-grid { grid-template-columns: 1fr; }
  .tactics-side { grid-template-columns: 1fr; }
  .tactics-diagram { grid-row: auto; }
  .plays-layout { grid-template-columns: 1fr; }
  .plays-list-panel { position: static; }
  .play-list { max-height: 140px; }
  .setup-team-row { grid-template-columns: 1fr auto 1fr; gap: 8px; }
  .setup-team { padding: 14px; }
  .setup-team h3 { font-size: 20px; }
  .st-kit { width: 32px; height: 42px; margin-bottom: 10px; }
  .st-rating b { font-size: 22px; }
  .vs-badge { width: 40px; height: 40px; font-size: 14px; }
  .opponent-grid { grid-template-columns: 1fr 1fr; }
  .setup-panel { padding: 16px; }
  .sb-name { font-size: 12px; }
  .sb-team { min-width: 88px; padding: 6px 9px; }
  .scoreboard { max-width: 94vw; }
  .hud-left { bottom: calc(230px + var(--safe-bottom)); }
  .player-card { width: 190px; }
  .hud-right { bottom: auto; top: calc(74px + var(--safe-top)); right: 10px; }
  .tactic-bar { display: none; }
  .menu-footer .footer-keys { display: none; }
  .menu-footer { justify-content: center; }
}
@media (max-width: 560px) {
  .title { font-size: 62px; }
  .menu-actions { flex-direction: column; align-items: stretch; }
  .menu-actions .btn { width: 100%; }
  .menu-actions .icon-btn { position: absolute; right: 0; bottom: 0; }
  .hero-tags { display: none; }
  .lede { font-size: 13px; margin-bottom: 20px; }
  .two-col { grid-template-columns: 1fr 1fr; }
  .roster-list { grid-template-columns: 1fr; }
  .hud-left { bottom: calc(232px + var(--safe-bottom)); left: 10px; }
  .player-card { width: 172px; padding: 6px 8px; }
  .pc-number { width: 26px; height: 26px; font-size: 16px; }
  .context-widget { bottom: calc(210px + var(--safe-bottom)); }
  .screen-vignette { background: radial-gradient(ellipse at center, transparent 55%, rgba(0,0,0,.3) 100%); }
