  await page.evaluate(() => window.__ruckus.startMatch({ opponent: 'sharks', half: 90, difficulty: 'normal', weather: 'clear' }));
  await page.waitForTimeout(300);

  // hold kick to charge, release
  await page.keyboard.down('KeyK');
  await sleep(900);
  await page.keyboard.up('KeyK');
  await sleep(600);
  console.log('after kickoff:', await page.evaluate(() => ({ state: window.__ruckus.match.state, owner: window.__ruckus.match.ball.owner?.name, ctrl: window.__ruckus.match.controlled?.name })));

  // run for 25 s with a simple bot
  const log = [];
  for (let i = 0; i < 25; i++) {
    const snap = await page.evaluate(() => {
      const m = window.__ruckus.match;
      return { state: m.state, clock: Math.round(m.clock), score: m.teams.map(t => t.score), ctrl: m.controlled?.name, cx: +(m.controlled?.x || 0).toFixed(1), cy: +(m.controlled?.y || 0).toFixed(1), owner: m.ball.owner?.team?.isUser === true ? 'user' : m.ball.owner ? 'away' : 'loose', poss: m.ball.owner?.team?.isUser };
    });
    log.push(snap);
    await page.keyboard.down('KeyD');
    await page.keyboard.down('ShiftLeft');
    await sleep(500);
    if (i % 3 === 2) await page.keyboard.press('KeyJ');
    if (i % 5 === 4) await page.keyboard.press('KeyL');
    if (i % 7 === 6) await page.keyboard.press('KeyQ');
    await sleep(200);
    await page.keyboard.up('ShiftLeft');
    await page.keyboard.up('KeyD');
    await sleep(300);
  }
  console.log('log:', JSON.stringify(log));
  console.log('final:', await page.evaluate(() => { const m = window.__ruckus.match; return { state: m.state, clock: m.clock, score: m.teams.map(t => t.score), stats: m.teams.map(t => t.stats), errors: 0 }; }));
  await page.screenshot({ path: path.join(OUT, 'qa-real-play.png') });
  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

