const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = require('node:path');
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, userAgent: devices['iPhone 13'].userAgent });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.tap('[data-go="setup"]');
  await page.waitForTimeout(300);
  await page.tap('#start-match-btn');
  await sleep(2600);
  // tap KICK once to kick off (min power)
  await page.tap('[data-action="kick"]');
  await sleep(700);
  console.log('after kick tap:', await page.evaluate(() => ({ state: window.__ruckus.match.state, clock: window.__ruckus.match.clock, score: window.__ruckus.match.teams.map(t => t.score) })));
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-kicked.png') });

  // tap controls
  for (const a of ['pass', 'tackle', 'switch', 'sidestep', 'sprint', 'kick']) {
    const b = page.locator(`[data-action="${a}"]`);
    if (await b.count()) { await b.tap({ force: true }).catch(() => {}); await sleep(250); }
  }
  await sleep(600);
  console.log('after actions:', await page.evaluate(() => ({ state: window.__ruckus.match.state, ctrl: window.__ruckus.match.controlled?.name, touch: document.body.classList.contains('touch-mode') })));
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-touch.png') });

  // try joystick via CDP touch hold + move
  const stick = await page.locator('#stick-zone').boundingBox();
  const client = await ctx.newCDPSession(page);
  const cx = stick.x + stick.width / 2, cy = stick.y + stick.height / 2;
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: cx, y: cy, id: 9 }] });
  await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: cx + 45, y: cy - 25, id: 9 }] });
  await sleep(1200);
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-joystick.png') });
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  console.log('knob transform:', await page.evaluate(() => document.getElementById('stick-knob').style.transform));

  // mobile playbook and squad
  await page.tap('#btn-pause');
  await page.waitForTimeout(300);
  await page.tap('[data-act="quit"]');
  await page.waitForTimeout(500);
  console.log('after quit:', await page.locator('.screen.active').getAttribute('id'));
  await page.tap('[data-go="playbook"]');
  await page.waitForTimeout(600);
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-playbook.png') });
  await page.tap('#screen-playbook [data-go="menu"]');
  await page.waitForTimeout(200);
  await page.tap('[data-go="squad"]');
  await page.waitForTimeout(600);
  await page.screenshot({ path: path.join(OUT, 'qa-mobile-squad.png') });
  console.log('squad scroll:', await page.evaluate(() => ({ sh: document.querySelector('#screen-squad').scrollHeight, ch: document.querySelector('#screen-squad').clientHeight, sw: document.querySelector('#screen-squad').scrollWidth, cw: document.querySelector('#screen-squad').clientWidth })));

  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

