const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, userAgent: devices['iPhone 13'].userAgent });
  const page = await ctx.newPage();
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.tap('[data-go="squad"]');
  await page.waitForTimeout(400);
  const res = await page.evaluate(() => {
    const scr = document.querySelector('#screen-squad');
    const out = [];
    const vw = innerWidth;
    for (const el of scr.querySelectorAll('*')) {
      const r = el.getBoundingClientRect();
      if (r.right > vw + 1 || r.width > vw + 1) {
        out.push({ tag: el.tagName, cls: el.className?.toString().slice(0, 40), id: el.id, right: Math.round(r.right), width: Math.round(r.width), sw: el.scrollWidth, cw: el.clientWidth });
      }
    }
    return { screen: { sw: scr.scrollWidth, cw: scr.clientWidth, ow: getComputedStyle(scr).overflowX }, vw, out: out.slice(0, 60) };
  });
  console.log(JSON.stringify(res, null, 1));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

