const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, userAgent: devices['iPhone 13'].userAgent });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.tap('[data-go="squad"]');
  await page.waitForTimeout(400);
  console.log('squad width:', await page.evaluate(() => ({ sw: document.querySelector('#screen-squad').scrollWidth, cw: document.querySelector('#screen-squad').clientWidth })));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/qa-mobile-squad2.png' });

  // start match & test kick via real touch tap
  await page.tap('#screen-squad [data-go="menu"]');
  await page.waitForTimeout(200);
  await page.tap('[data-go="setup"]');
  await page.waitForTimeout(200);
  await page.tap('#start-match-btn');
  await sleep(2600);
  await page.tap('[data-action="kick"]');
  await sleep(900);
  console.log('after kick tap:', await page.evaluate(() => ({ state: window.__ruckus.match.state, clock: window.__ruckus.match.clock })));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/qa-mobile-kicked2.png' });

  // joystick via mouse drag
  const stick = await page.locator('#stick-zone').boundingBox();
  const cx = stick.x + stick.width / 2, cy = stick.y + stick.height / 2;
  await page.mouse.move(cx, cy);
  await page.mouse.down();
  await page.mouse.move(cx + 45, cy - 30, { steps: 5 });
  await sleep(1000);
  console.log('knob during drag:', await page.evaluate(() => document.getElementById('stick-knob').style.transform));
  await page.mouse.up();
  await sleep(200);
  console.log('knob after drag:', await page.evaluate(() => document.getElementById('stick-knob').style.transform));

  // open playbook mobile width
  await page.tap('#btn-pause');
  await page.waitForTimeout(300);
  await page.tap('[data-act="quit"]');
  await page.waitForTimeout(300);
  await page.tap('[data-go="playbook"]');
  await page.waitForTimeout(400);
  console.log('playbook width:', await page.evaluate(() => ({ sw: document.querySelector('#screen-playbook').scrollWidth, cw: document.querySelector('#screen-playbook').clientWidth })));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/qa-mobile-playbook2.png' });
  await page.tap('.playbook-tabs .tab[data-tab="plays"]');
  await page.waitForTimeout(400);
  console.log('playbook plays width:', await page.evaluate(() => ({ sw: document.querySelector('#screen-playbook').scrollWidth, cw: document.querySelector('#screen-playbook').clientWidth })));
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/qa-mobile-plays2.png' });

  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

