const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('node:fs');

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.evaluate(() => window.__ruckus.startMatch({ opponent: 'bulls', half: 90, difficulty: 'normal', weather: 'clear' }));
  await page.waitForTimeout(200);
  const res = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    ui.paused = true;
    let i = 0, halftimeSeen = 0, conversions = 0, setpieces = 0, tries = 0, nan = false;
    const max = 60 * 60 * 8;
    while (i++ < max) {
      if (m.state === 'kickoff') { m.kickoffKick(true); m.update(1 / 60); continue; }
      if (m.state === 'halftime') { halftimeSeen++; m.startSecondHalf(); m.update(1 / 60); continue; }
      if (m.state === 'fulltime') break;
      if (m.state === 'conversion' && m.conversion && !m.conversion.locked) {
        m.conversion.power = 0.7;
        m.lockConversion();
        conversions++;
      }
      if ((m.state === 'lineout' || m.state === 'scrum') && m.setpiece && m.setpiece.phase === 'timing' && m.setpiece.team.isUser) {
        m.setpiece.bar = (m.setpiece.zone[0] + m.setpiece.zone[1]) / 2;
        m.stopSetpieceBar();
        setpieces++;
      }
      m.update(1 / 60);
      if (m.state === 'try') tries++;
      if (!Number.isFinite(m.clock) || m.teams.some(t => !Number.isFinite(t.score))) { nan = true; break; }
    }
    return {
      i, state: m.state, half: m.half, clock: m.clock, nan,
      score: m.teams.map(t => t.score), halftimeSeen, conversions, setpieces, tries,
      stats: m.teams.map(t => ({ ...t.stats, meters: Math.round(t.stats.meters) })),
      overlay: ui.overlayOpen,
      results: m.state === 'fulltime' ? m.buildResults() : null,
    };
  });
  console.log(JSON.stringify(res, (k, v) => k === 'squad' ? undefined : v, 1));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/qa-fulltime-sim.png' });
  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

