const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  const ids = await page.evaluate(() => window.__ruckus.save.plays.map(p => p.id));
  console.log('ids:', ids);
  await page.evaluate((ids) => {
    const s = window.__ruckus.save;
    s.equipped = [ids[0], null, ids[2], null];
    window.__ruckus.ui.persist();
  }, ids);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  console.log('equipped after reload (gap preserved?):', await page.evaluate(() => window.__ruckus.save.equipped));
  const ids2 = await page.evaluate(() => window.__ruckus.save.plays.map(p => p.id));
  console.log('expected gap at 1 and 3:', [ids2[0], null, ids2[2], null]);
  // UI ensures and equip selects reflect holes
  await page.click('[data-go="playbook"]');
  await page.waitForTimeout(300);
  await page.click('.playbook-tabs .tab[data-tab="plays"]');
  await page.waitForTimeout(200);
  console.log('slot values:', await page.evaluate(() => [...document.querySelectorAll('#equip-slots select')].map(s => s.value)));
  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

