const { chromium, devices } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await sleep(700);
  // screen overflow check desktop
  for (const s of ['menu', 'setup', 'squad', 'playbook', 'help', 'settings']) {
    await page.click(`[data-go="${s}"]`).catch(async () => {
      await page.click(`#screen-playbook [data-go="${s}"]`).catch(() => {});
    });
    await sleep(200);
    const m = await page.evaluate((id) => { const el = document.getElementById('screen-' + id); return el ? { sw: el.scrollWidth, cw: el.clientWidth } : null; }, s);
    console.log('desktop', s, m);
    if (s !== 'menu') await page.click(`#screen-${s} [data-go="menu"]`).catch(() => {});
    await sleep(150);
  }
  // fulltime -> run it back
  await page.click('[data-go="setup"]');
  await sleep(200);
  await page.click('#start-match-btn');
  await sleep(400);
  const runBack = await page.evaluate(() => {
    const m = window.__ruckus.match;
    const ui = window.__ruckus.ui;
    ui.paused = true;
    m.finishMatch();
    ui.paused = false;
    return { state: m.state, overlay: ui.overlayOpen };
  });
  await sleep(200);
  console.log('fulltime:', runBack);
  const btn = await page.locator('[data-act="again"]').count();
  console.log('run back button:', btn);
  await page.click('[data-act="again"]');
  await sleep(600);
  console.log('after run back:', await page.evaluate(() => ({ state: window.__ruckus.match?.state, score: window.__ruckus.match?.teams.map(t => t.score), screen: window.__ruckus.ui.screen })));
  // back to menu from pause
  await page.click('#btn-pause');
  await sleep(250);
  await page.click('[data-act="menu"]').catch(async () => { await page.click('[data-act="quit"]'); });
  await sleep(300);
  console.log('after quit:', await page.evaluate(() => ({ screen: window.__ruckus.ui.screen, match: !!window.__ruckus.match })));

  // mobile all screen overflow + shots
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, userAgent: devices['iPhone 13'].userAgent });
  const pm = await ctx.newPage();
  pm.on('console', m => { if (m.type() === 'error') errors.push('mobile console: ' + m.text()); });
  pm.on('pageerror', e => errors.push('mobile pageerror: ' + e.message));
  await pm.goto('http://localhost:3000/?qa=' + Date.now(), { waitUntil: 'networkidle' });
  await sleep(600);
  for (const s of ['setup', 'squad', 'playbook', 'help', 'settings']) {
    await pm.tap(`[data-go="${s}"]`);
    await sleep(350);
    const m = await pm.evaluate((id) => { const el = document.getElementById('screen-' + id); return el ? { sw: el.scrollWidth, cw: el.clientWidth, sh: el.scrollHeight, ch: el.clientHeight } : null; }, s);
    console.log('mobile', s, m);
    if (s === 'playbook') { await pm.tap('.playbook-tabs .tab[data-tab="plays"]'); await sleep(300); console.log('mobile playbook plays', await pm.evaluate(() => { const el = document.getElementById('screen-playbook'); return { sw: el.scrollWidth, cw: el.clientWidth }; })); await pm.screenshot({ path: OUT + '/qa-final-mobile-plays.png' }); }
    if (s === 'squad') await pm.screenshot({ path: OUT + '/qa-final-mobile-squad.png' });
    await pm.tap(`#screen-${s} [data-go="menu"]`).catch(() => {});
    await sleep(200);
  }
  console.log('errors:', errors.length ? errors : 'none');
