input.content:
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3000/?v=final-' + Date.now(), { waitUntil: 'networkidle' });
  await sleep(700);
  console.log('menu:', await page.locator('.screen.active').getAttribute('id'));
  await page.click('[data-go="setup"]');
  await sleep(250);
  await page.click('#start-match-btn');
  await sleep(2600);
  await page.keyboard.down('KeyK');
  await sleep(700);
  await page.keyboard.up('KeyK');
  await sleep(1500);
  console.log('game:', await page.evaluate(() => {
    const m = window.__ruckus.match;
    return { state: m.state, clock: +m.clock.toFixed(1), players: m.teams.map(t => t.players.length), score: m.teams.map(t => t.score), cam: +window.__ruckus.renderer.cam.scale.toFixed(1) };
  }));
  await page.screenshot({ path: '/tmp/opencode/final-game.png' });
  // custom play keyboard after giving possession
  await page.evaluate(() => {
    const m = window.__ruckus.match;
    m.state = 'play';
    const c = m.controlled;
    c.x = 55; c.y = 35; c.state = 'run';
    m.ball.state = 'held'; m.ball.owner = c; m.ball.x = c.x; m.ball.y = c.y;
    m.contact = null; m.ruck = null; m.setpiece = null; m.activePlay = null; m.playCd = 0;
  });
  await page.keyboard.press('Digit2');
  await sleep(300);
  console.log('play:', await page.evaluate(() => ({ active: window.__ruckus.match.activePlay?.play?.name, banner: document.getElementById('play-banner-name').textContent })));
  await page.screenshot({ path: '/tmp/opencode/final-setplay.png' });
  console.log('errors:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

